import 'dart:io';import 'package:cloud_firestore/cloud_firestore.dart';import 'package:firebase_storage/firebase_storage.dart';import 'package:flutter/material.dart';import 'package:image_picker/image_picker.dart';class BannersAdminPage extends StatelessWidget{const BannersAdminPage({super.key});Future<void> upload()async{final x=await ImagePicker().pickImage(source:ImageSource.gallery,imageQuality:85);if(x==null)return;final ref=FirebaseStorage.instance.ref('banners/'+DateTime.now().millisecondsSinceEpoch.toString()+'.jpg');await ref.putFile(File(x.path));final url=await ref.getDownloadURL();await FirebaseFirestore.instance.collection('banners').add({'title':'Promo','imageUrl':url,'active':true,'createdAt':FieldValue.serverTimestamp()});}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Banner & Promo')),floatingActionButton:FloatingActionButton(onPressed:upload,child:const Icon(Icons.add_photo_alternate)),body:StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection('banners').snapshots(),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());return ListView(children:s.data!.docs.map((d){final x=d.data();return ListTile(title:Text(x['title']??'Banner'),trailing:IconButton(icon:const Icon(Icons.delete_outline),onPressed:()=>d.reference.delete()));}).toList());}));}